    "relationship_tension": ["政治任务vs旧情", "组织纪律vs个人情感"],
    "user_preferences": {
      "desired_emotion": "压抑中无声崩溃的绝望感",
      "forbidden": ["HE转折", "承认旧情"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "G36",
    "x_axis_mode_name": "失去所爱",
    "y_axis_tags": ["商战权谋", "规则怪谈", "双向暗恋"],
    "reaction_strength": "↘",
    "tension_stars": 5,
    "forbidden_elements": ["HE", "甜宠", "轻松搞笑", "第三者插足"],
    "x_axis_display": "两人在体制的重压下，注定失去彼此，最终失去生命。",
